using UnityEngine;
namespace ROM.Horde {
public sealed class FracturedHeart:MonoBehaviour {
 public Light WorldLight;public Transform Crystal,Fragments;public Color Calm=new Color(.63f,.67f,1),Storm=new Color(.72f,.3f,1);[Range(0,1)]public float Intensity;public float BaseLight=.85f,PulseStrength=.04f,PulsePeriod=18;float visual;
 public void Transition(float energy){Intensity=Mathf.Clamp01(energy);}
 void Update(){if(!Application.isPlaying)return;visual=Mathf.MoveTowards(visual,Intensity,Time.deltaTime*.1f);float wave=Mathf.Sin(Time.time*Mathf.PI*2/PulsePeriod);if(Crystal)Crystal.Rotate(0,Time.deltaTime*1.5f,0,Space.Self);if(Fragments)Fragments.Rotate(Vector3.up,Time.deltaTime*-2,Space.Self);if(WorldLight){WorldLight.color=Color.Lerp(Calm,Storm,visual);WorldLight.intensity=BaseLight*(1+wave*PulseStrength+visual*.15f);} }
 readonly System.Collections.Generic.Dictionary<Renderer,bool> uiHidden=new System.Collections.Generic.Dictionary<Renderer,bool>();Renderer[] presentation;ROM.UI.Sprint01.RiftHub ui;readonly Vector3[] uiCorners=new Vector3[4];public int UIHiddenCount=>uiHidden.Count;
 ROM.UI.Gameplay.RiftFieldUI mapUI;
 void LateUpdate(){if(!Application.isPlaying)return;if(!mapUI)mapUI=FindFirstObjectByType<ROM.UI.Gameplay.RiftFieldUI>();if(mapUI&&mapUI.MapOpen){if(presentation==null)presentation=GetComponentsInChildren<Renderer>(true);foreach(var renderer in presentation){if(!uiHidden.ContainsKey(renderer))uiHidden[renderer]=renderer.forceRenderingOff;renderer.forceRenderingOff=true;}return;}if(!MultiFPS.UI.ClientFrontend.Pause){RestoreUI();return;}if(!ui&&MultiFPS.UI.UIPauseMenu._instance)ui=MultiFPS.UI.UIPauseMenu._instance.pauseMenuOverlay.GetComponentInChildren<ROM.UI.Sprint01.RiftHub>(true);var camera=MultiFPS.GameplayCamera._instance?MultiFPS.GameplayCamera._instance.GetComponent<Camera>():null;if(!ui||!ui.Design||!camera){RestoreUI();return;}var page=ui.Design.Find("Screen/PagePanel") as RectTransform;var header=ui.Design.Find("Modern inventory navigation") as RectTransform;if(presentation==null)presentation=GetComponentsInChildren<Renderer>(true);foreach(var renderer in presentation){if(!renderer)continue;bool hide=Overlaps(page,camera,renderer)||Overlaps(header,camera,renderer);if(hide){if(!uiHidden.ContainsKey(renderer))uiHidden[renderer]=renderer.forceRenderingOff;renderer.forceRenderingOff=true;}else if(uiHidden.TryGetValue(renderer,out bool previous)){renderer.forceRenderingOff=previous;uiHidden.Remove(renderer);}}}
 bool Overlaps(RectTransform panel,Camera camera,Renderer renderer){if(!panel||!panel.gameObject.activeInHierarchy)return false;panel.GetWorldCorners(uiCorners);var bottom=RectTransformUtility.WorldToScreenPoint(null,uiCorners[0]);var top=RectTransformUtility.WorldToScreenPoint(null,uiCorners[2]);var box=renderer.bounds;Vector2 min=new Vector2(float.PositiveInfinity,float.PositiveInfinity),max=new Vector2(float.NegativeInfinity,float.NegativeInfinity);bool front=false;for(int i=0;i<8;i++){var p=camera.WorldToScreenPoint(box.center+Vector3.Scale(box.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(p.z<=0)continue;front=true;min=Vector2.Min(min,p);max=Vector2.Max(max,p);}return front&&Rect.MinMaxRect(bottom.x,bottom.y,top.x,top.y).Overlaps(Rect.MinMaxRect(min.x,min.y,max.x,max.y));}
 void RestoreUI(){foreach(var pair in uiHidden)if(pair.Key)pair.Key.forceRenderingOff=pair.Value;uiHidden.Clear();}
 void OnDisable()=>RestoreUI();
}
}
